'use client';
import { useState } from 'react';
import MessageList from './MessageList';
import PromptInput from './PromptInput';
import ChatSidebar from './ChatSidebar';
import EmptyState from './EmptyState';

type Message = {
  role: 'user' | 'assistant';
  content: string;
};

export default function ChatLayout() {
  const [messages, setMessages] = useState<Message[]>([]);

  const addUserMessage = (text: string) => {
    const userMsg: Message = { role: 'user', content: text };
    setMessages(prev => [...prev, userMsg]);
    mockAssistantReply(text);
  };

  const mockAssistantReply = (prompt: string) => {
    const reply = `This is a mock response to "${prompt}"`;
    const assistantIndex = messages.length; // index where assistant will be added
    // add placeholder assistant message
    setMessages(prev => [...prev, { role: 'assistant', content: '' }]);
    let idx = 0;
    const interval = setInterval(() => {
      idx++;
      setMessages(prev => {
        const newMsgs = [...prev];
        if (assistantIndex < newMsgs.length) {
          newMsgs[assistantIndex] = {
            ...newMsgs[assistantIndex],
            content: reply.slice(0, idx),
          };
        }
        return newMsgs;
      });
      if (idx >= reply.length) {
        clearInterval(interval);
      }
    }, 50);
  };

  return (
    <div className="flex h-screen">
      <ChatSidebar />
      <main className="flex-1 flex flex-col">
        {messages.length === 0 ? (
          <EmptyState />
        ) : (
          <MessageList messages={messages} />
        )}
        <PromptInput onSend={addUserMessage} />
      </main>
    </div>
  );
}

